      detailEl.querySelectorAll('[data-pm-package]').forEach(b=>b.onclick=async()=>{const scenarioId=document.getElementById("pmPackageScenario")?.value,evidenceIds=(brainCache[selected]?.artifacts||[]).map(x=>x.id).filter(Boolean);try{const d=await opsApi({action:"createDecisionPackage",projectId:selected,scenarioId,evidenceIds,title:"投资决策包"});alert(d.package.audit.passed?"投资决策包已通过提交前审计":"决策包已生成但被阻断：\n- "+d.package.audit.blockers.join("\n- "));delete opsCache[selected];await loadOps(selected);}catch(e){alert(e.message);}});
      detailEl.querySelectorAll('[data-pm-golden]').forEach(b=>b.onclick=async()=>{const numericErrors=prompt("关键数字错误数（必须如实填写）","0");if(numericErrors===null)return;const evidenceCoverage=prompt("证据覆盖率（0—100）","80");if(evidenceCoverage===null)return;const manualMinutes=prompt("人工耗时（分钟）","");if(manualMinutes===null)return;try{await opsApi({action:"saveEvaluation",projectId:selected,type:"golden_project",status:Number(numericErrors)===0?"recorded":"failed",result:{numericErrors:Number(numericErrors)||0,evidenceCoverage:Number(evidenceCoverage)||0,manualMinutes:Number(manualMinutes)||0,recordedAt:Date.now()}});delete opsCache[selected];await loadOps(selected);}catch(e){alert(e.message);}});
      detailEl.querySelectorAll('[data-pm-slo]').forEach(b=>b.onclick=async()=>{const concurrency=prompt("实测并发人数（目标50）","50");if(concurrency===null)return;const p95Ms=prompt("核心路径P95耗时（毫秒）","5000");if(p95Ms===null)return;const successRate=prompt("成功率（0—100）","99");if(successRate===null)return;const recoveryRate=prompt("失败恢复率（0—100）","95");if(recoveryRate===null)return;const result={concurrency:Number(concurrency)||0,p95Ms:Number(p95Ms)||0,successRate:(Number(successRate)||0)/100,recoveryRate:(Number(recoveryRate)||0)/100,passed:Number(concurrency)>=50&&Number(p95Ms)<=5000&&Number(successRate)>=99&&Number(recoveryRate)>=95};try{await opsApi({action:"saveEvaluation",projectId:selected,type:"slo_load",status:result.passed?"passed":"failed",result});delete opsCache[selected];await loadOps(selected);}catch(e){alert(e.message);}});
