      async function openEditor(b,id){b.disabled=true;try{if(options.preserveDraft&&(await options.preserveDraft({projectId:selected,view,viewStageKey}))===false)throw new Error('保存失败，未切换到 AI 可研。');if(options.openAiReport)await options.openAiReport(id);else if(options.openProject)await options.openProject(id);if(!overlay.isConnected)activeCleanup?.();}catch(e){alert(e.message||"进入 AI 可研失败，已保留当前页面。");}finally{b.disabled=false;}}
