    document.querySelectorAll('[data-pm-tab]').forEach(b=>{if(b.dataset.pmTab==='archived')b.textContent='已归档 / 已废止';b.onclick=()=>{tab=b.dataset.pmTab;document.querySelectorAll('[data-pm-tab]').forEach(x=>x.classList.toggle("active",x===b));loadResearch();};});
    document.querySelectorAll('[data-pm-head-view]').forEach(b=>{if(b.dataset.pmHeadView!=="library")b.textContent="本项目 · "+({data:"数据",decisions:"决策",versions:"成果"}[b.dataset.pmHeadView]||"");b.onclick=()=>{const next=b.dataset.pmHeadView;if(next!=="library"&&!projects.some(p=>p.id===selected)){alert("请先从项目库选择项目；数据、决策和成果均属于所选项目。");return;}return navigate(selected,next);};});
