    overlay.addEventListener('click',async e=>{const b=e.target.closest('[data-portfolio-info]');if(!b)return;const p=projects.find(p=>p.id===b.dataset.portfolioInfo);if(!p?.portfolio)return;const {portfolioCard}=await import('./project-map/portfolio-ui.mjs');const d=document.createElement('dialog'),close=document.createElement('button');close.textContent='关闭';close.onclick=()=>d.close();d.append(close,portfolioCard(p.portfolio));d.style.cssText='width:min(650px,90vw);border:0;background:#fff6cf;border-radius:12px';document.body.append(d);d.onclose=()=>d.remove();d.showModal();});
